"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Bottom Sheet: generated by UIX from the design system. Same variants and sizes as the Figma component.

export interface SheetAction {
  label: React.ReactNode;
  icon?: React.ReactNode;
  destructive?: boolean;
  onSelect?: () => void;
}

const sheetVariants = cva(
  "m-0 mt-auto mb-0 w-full max-w-none overflow-y-auto rounded-t-2xl p-0 bg-surface text-fg-primary shadow-xl backdrop:bg-base-black/50",
);

export interface SheetProps
  extends Omit<React.DialogHTMLAttributes<HTMLDialogElement>, "title" | "open" | "onClose">,
    VariantProps<typeof sheetVariants> {
  open: boolean;
  onClose: () => void;
  title?: React.ReactNode;
  /** Rows of icon + label; pressing one calls its onSelect and closes the sheet. */
  actions?: SheetAction[];
  /** Buttons under the content (a full-width Button works well). */
  footer?: React.ReactNode;
}

const Sheet = React.forwardRef<HTMLDialogElement, SheetProps>(
  ({ className, open, onClose, title, actions, footer, children, ...props }, ref) => {
    const inner = React.useRef<HTMLDialogElement>(null);
    React.useImperativeHandle(ref, () => inner.current as HTMLDialogElement);
    React.useEffect(() => {
      const dialog = inner.current;
      if (!dialog) return;
      if (open && !dialog.open) dialog.showModal();
      if (!open && dialog.open) dialog.close();
    }, [open]);
    const titleId = React.useId();
    return (
      <dialog data-slot="sheet" data-kind="overlay"
        ref={inner}
        aria-labelledby={title ? titleId : void 0}
        className={cn(sheetVariants(), className)}
        onClose={onClose}
        onClick={(event) => {
          if (event.target === event.currentTarget) onClose();
        }}
        {...props}
      >
        <div className="mx-auto flex max-w-md flex-col gap-4 px-5 pt-3 pb-5">
          <span aria-hidden className="mx-auto h-1 w-10 rounded-full bg-muted" />
          {title ? <h2 id={titleId} className="text-title-large text-fg-primary">{title}</h2> : null}
          {actions?.length ? (
            <div className="flex flex-col gap-0-5">
              {actions.map((action, index) => (
                <button key={index} type="button" onClick={() => {
                  action.onSelect?.();
                  onClose();
                }} className={cn("inline-flex items-center h-[52px] px-3 gap-3 w-full cursor-pointer rounded-md text-left text-body-large hover:bg-subtle focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus [&_svg]:size-5 [&_svg]:shrink-0", action.destructive ? "text-fg-danger [&_svg]:text-icon-danger" : "text-fg-primary [&_svg]:text-icon-secondary")}>
                  {action.icon}
                  {action.label}
                </button>
              ))}
            </div>
          ) : null}
          {children ? <div className="text-body-medium text-fg-secondary">{children}</div> : null}
          {footer}
        </div>
      </dialog>
    );
  },
);
Sheet.displayName = "Sheet";

export { Sheet, sheetVariants };
